impl Cli {
    // Behavior-preserving extraction for the configuration regression controls.
    pub fn apply_config(&mut self, file_config: Config, _matches: &clap::ArgMatches) {
        self.data_dir = file_config.data_dir.or(self.data_dir.take());
        self.log_level = super::effective_log_filter(&self.log_level, file_config.log_level);
        self.partition_target_rows = file_config
            .partition_target_rows
            .unwrap_or(self.partition_target_rows);
        self.checkpoint = file_config.checkpoint.or(self.checkpoint.take());
        self.checkpoint_sync_url = file_config
            .checkpoint_sync_url
            .or(self.checkpoint_sync_url.take());
        if let Command::Sync {
            http_host,
            grpc_host,
            nat,
            p2p_bind_ip,
            execution_bootnodes,
            execution_discv5_port,
            allow_public_grpc,
            disable_dashboard,
            dashboard_password,
            ..
        } = &mut self.command
        {
            if nat == "any" {
                *nat = file_config.nat.unwrap_or_else(|| std::mem::take(nat));
            }
            *http_host = file_config.http_host.unwrap_or(*http_host);
            *grpc_host = file_config.grpc_host.unwrap_or(*grpc_host);
            *p2p_bind_ip = file_config.p2p_bind_ip.or(*p2p_bind_ip);
            if execution_bootnodes.is_empty() {
                *execution_bootnodes = file_config.execution_bootnodes.unwrap_or_default();
            }
            *execution_discv5_port = file_config
                .execution_discv5_port
                .unwrap_or(*execution_discv5_port);
            *allow_public_grpc = file_config.allow_public_grpc.unwrap_or(*allow_public_grpc);
            *disable_dashboard =
                !(file_config.dashboard_enabled.unwrap_or(true) && !*disable_dashboard);
            *dashboard_password = dashboard_password.take().or(file_config.dashboard_password);
        }
    }
}
